import PracticeSession from '../models/practiceSession.model';
import { connect } from '../mongodb/mongoose';

/**
 * Get total practice sessions for a user
 * @param {string} clerkId - The Clerk ID of the user
 * @returns {Promise<number>} - The total number of practice sessions
 */
export const getTotalPracticeSessions = async (clerkId) => {
  try {
    await connect();
    const count = await PracticeSession.countDocuments({ clerkId });
    return count;
  } catch (error) {
    console.error('Error getting total practice sessions:', error);
    return 0;
  }
};

/**
 * Get the percentage change in practice sessions compared to previous period
 * @param {string} clerkId - The Clerk ID of the user
 * @param {number} days - Number of days to compare (default: 30)
 * @returns {Promise<number>} - The percentage change
 */
export const getPracticeSessionsChange = async (clerkId, days = 30) => {
  try {
    await connect();
    
    const currentDate = new Date();
    const previousPeriodStart = new Date();
    previousPeriodStart.setDate(currentDate.getDate() - (days * 2));
    const currentPeriodStart = new Date();
    currentPeriodStart.setDate(currentDate.getDate() - days);
    
    // Count sessions in current period
    const currentPeriodCount = await PracticeSession.countDocuments({
      clerkId,
      sessionDate: { $gte: currentPeriodStart, $lte: currentDate }
    });
    
    // Count sessions in previous period
    const previousPeriodCount = await PracticeSession.countDocuments({
      clerkId,
      sessionDate: { $gte: previousPeriodStart, $lt: currentPeriodStart }
    });
    
    // Calculate percentage change
    if (previousPeriodCount === 0) {
      return currentPeriodCount > 0 ? 100 : 0; // If no previous sessions, return 100% increase if there are current sessions
    }
    
    const percentageChange = ((currentPeriodCount - previousPeriodCount) / previousPeriodCount) * 100;
    return Math.round(percentageChange);
  } catch (error) {
    console.error('Error calculating practice sessions change:', error);
    return 0;
  }
};

/**
 * Get average score for a user's practice sessions
 * @param {string} clerkId - The Clerk ID of the user
 * @returns {Promise<number>} - The average score
 */
export const getAverageScore = async (clerkId) => {
  try {
    await connect();
    const result = await PracticeSession.aggregate([
      { $match: { clerkId } },
      { $group: { _id: null, averageScore: { $avg: '$score' } } }
    ]);
    
    return result.length > 0 ? Math.round(result[0].averageScore) : 0;
  } catch (error) {
    console.error('Error getting average score:', error);
    return 0;
  }
};

/**
 * Get the percentage change in average score compared to previous period
 * @param {string} clerkId - The Clerk ID of the user
 * @param {number} days - Number of days to compare (default: 30)
 * @returns {Promise<number>} - The percentage change
 */
export const getAverageScoreChange = async (clerkId, days = 30) => {
  try {
    await connect();
    
    const currentDate = new Date();
    const previousPeriodStart = new Date();
    previousPeriodStart.setDate(currentDate.getDate() - (days * 2));
    const currentPeriodStart = new Date();
    currentPeriodStart.setDate(currentDate.getDate() - days);
    
    // Get average score in current period
    const currentPeriodResult = await PracticeSession.aggregate([
      { 
        $match: { 
          clerkId,
          sessionDate: { $gte: currentPeriodStart, $lte: currentDate }
        } 
      },
      { $group: { _id: null, averageScore: { $avg: '$score' } } }
    ]);
    
    // Get average score in previous period
    const previousPeriodResult = await PracticeSession.aggregate([
      { 
        $match: { 
          clerkId,
          sessionDate: { $gte: previousPeriodStart, $lt: currentPeriodStart }
        } 
      },
      { $group: { _id: null, averageScore: { $avg: '$score' } } }
    ]);
    
    const currentAvg = currentPeriodResult.length > 0 ? currentPeriodResult[0].averageScore : 0;
    const previousAvg = previousPeriodResult.length > 0 ? previousPeriodResult[0].averageScore : 0;
    
    // Calculate percentage change
    if (previousAvg === 0) {
      return currentAvg > 0 ? 100 : 0;
    }
    
    const percentageChange = ((currentAvg - previousAvg) / previousAvg) * 100;
    return Math.round(percentageChange);
  } catch (error) {
    console.error('Error calculating average score change:', error);
    return 0;
  }
};

/**
 * Get total vocabulary growth (sum of new words used in sessions)
 * @param {string} clerkId - The Clerk ID of the user
 * @returns {Promise<number>} - The total vocabulary growth
 */
export const getVocabularyGrowth = async (clerkId) => {
  try {
    await connect();
    const result = await PracticeSession.aggregate([
      { $match: { clerkId } },
      { $group: { _id: null, totalNewWords: { $sum: '$newWords' } } }
    ]);
    
    return result.length > 0 ? result[0].totalNewWords : 0;
  } catch (error) {
    console.error('Error getting vocabulary growth:', error);
    return 0;
  }
};

/**
 * Get the vocabulary growth change compared to previous period
 * @param {string} clerkId - The Clerk ID of the user
 * @returns {Promise<number>} - The vocabulary growth change
 */
export const getVocabularyGrowthChange = async (clerkId) => {
  try {
    await connect();
    
    // Get the most recent 10 sessions
    const recentSessions = await PracticeSession.find({ clerkId })
      .sort({ sessionDate: -1 })
      .limit(10);
    
    if (recentSessions.length === 0) return 0;
    
    // Calculate the sum of new words in recent sessions
    const recentNewWords = recentSessions.reduce((sum, session) => sum + (session.newWords || 0), 0);
    
    return recentNewWords;
  } catch (error) {
    console.error('Error getting vocabulary growth change:', error);
    return 0;
  }
};

/**
 * Get current streak (consecutive days with practice sessions)
 * @param {string} clerkId - The Clerk ID of the user
 * @returns {Promise<number>} - The current streak in days
 */
export const getCurrentStreak = async (clerkId) => {
  try {
    await connect();
    
    // Get all sessions sorted by date descending
    const sessions = await PracticeSession.find({ clerkId })
      .sort({ sessionDate: -1 });
    
    if (sessions.length === 0) return 0;
    
    let streak = 0;
    let currentDate = new Date();
    currentDate.setHours(0, 0, 0, 0); // Set to beginning of day
    
    // Check if there's a session today
    const mostRecentSession = new Date(sessions[0].sessionDate);
    mostRecentSession.setHours(0, 0, 0, 0);
    
    // If most recent session is not today or yesterday, streak is 0
    const dayDifference = Math.floor((currentDate - mostRecentSession) / (1000 * 60 * 60 * 24));
    if (dayDifference > 1) return 0;
    
    // If most recent session is today, start streak at 1
    if (dayDifference === 0) {
      streak = 1;
      currentDate.setDate(currentDate.getDate() - 1); // Move to yesterday
    }
    
    // Check consecutive days
    for (let i = 0; i < sessions.length; i++) {
      const sessionDate = new Date(sessions[i].sessionDate);
      sessionDate.setHours(0, 0, 0, 0);
      
      if (sessionDate.getTime() === currentDate.getTime()) {
        streak++;
        currentDate.setDate(currentDate.getDate() - 1);
      } else if (sessionDate.getTime() < currentDate.getTime()) {
        break; // Streak is broken
      }
    }
    
    return streak;
  } catch (error) {
    console.error('Error calculating current streak:', error);
    return 0;
  }
};

/**
 * Get streak change (compared to previous best streak)
 * @param {string} clerkId - The Clerk ID of the user
 * @returns {Promise<number>} - The streak change
 */
export const getStreakChange = async (clerkId) => {
  try {
    await connect();
    
    const currentStreak = await getCurrentStreak(clerkId);
    
    // For simplicity, we'll return a positive number if streak > 3, otherwise 0
    return currentStreak > 3 ? currentStreak - 3 : 0;
  } catch (error) {
    console.error('Error calculating streak change:', error);
    return 0;
  }
};
