"use client";

import React, { useState } from "react";
import { motion } from "framer-motion";
import { widgetThemes } from "../../../utils/colorPalette";

const StatCard = ({
  title,
  value,
  change,
  icon,
  theme = "blue",
  delay = 0,
  subtitle
}) => {
  const [isHovered, setIsHovered] = useState(false);
  const themeStyles = widgetThemes[theme] || widgetThemes.blue;
  const isPositive = change && change.startsWith('+');

  // Generate glow color based on theme
  const glowColor = {
    blue: "rgba(59, 130, 246, 0.5)", // blue-500
    purple: "rgba(139, 92, 246, 0.5)", // purple-500
    green: "rgba(34, 197, 94, 0.5)", // green-500
    yellow: "rgba(234, 179, 8, 0.5)", // yellow-500
    red: "rgba(239, 68, 68, 0.5)", // red-500
  }[theme] || "rgba(59, 130, 246, 0.5)";

  return (
    <motion.div
      initial={{ opacity: 0, y: 20 }}
      animate={{
        opacity: 1,
        y: 0,
        boxShadow: isHovered ? `0 0 20px ${glowColor}` : "0 10px 15px -3px rgba(0, 0, 0, 0.1), 0 4px 6px -2px rgba(0, 0, 0, 0.05)"
      }}
      transition={{
        duration: 0.5,
        delay,
        boxShadow: { duration: 0.3 }
      }}
      className={`rounded-xl border ${themeStyles.border} bg-gradient-to-br from-gray-900/80 to-gray-950/80 p-5 backdrop-blur-sm shadow-lg relative overflow-hidden`}
      onMouseEnter={() => setIsHovered(true)}
      onMouseLeave={() => setIsHovered(false)}
      whileHover={{ scale: 1.02 }}
    >
      {/* Background pattern */}
      <div className="absolute inset-0 opacity-5 pointer-events-none overflow-hidden">
        <svg width="100%" height="100%" xmlns="http://www.w3.org/2000/svg">
          <defs>
            <pattern id={`grid-stat-${theme}`} width="20" height="20" patternUnits="userSpaceOnUse">
              <path d="M 20 0 L 0 0 0 20" fill="none" stroke="white" strokeWidth="0.5"/>
            </pattern>
          </defs>
          <rect width="100%" height="100%" fill={`url(#grid-stat-${theme})`} />
        </svg>
      </div>

      {/* Animated corner accent */}
      <motion.div
        className={`absolute top-0 right-0 w-16 h-16 bg-gradient-to-bl ${themeStyles.text.replace('text-', 'from-').replace('400', '600')} to-transparent opacity-20 rounded-bl-full`}
        initial={{ scale: 0, opacity: 0 }}
        animate={{ scale: 1, opacity: 0.2 }}
        transition={{ duration: 0.7, delay: delay + 0.3 }}
      />

      <div className="flex items-center relative z-10">
        <motion.div
          className={`p-3 rounded-lg ${themeStyles.border} bg-opacity-20 mr-4 relative overflow-hidden backdrop-blur-sm`}
          initial={{ opacity: 0, scale: 0 }}
          animate={{ opacity: 1, scale: 1 }}
          transition={{
            type: "spring",
            stiffness: 300,
            damping: 20,
            delay: delay + 0.1
          }}
          whileHover={{
            scale: 1.1,
            boxShadow: `0 0 10px ${glowColor}`
          }}
        >
          {/* Icon background glow */}
          <motion.div
            className="absolute inset-0 opacity-30 rounded-lg"
            style={{
              background: `radial-gradient(circle, ${glowColor} 0%, transparent 70%)`
            }}
            animate={{
              opacity: isHovered ? [0.3, 0.5, 0.3] : 0.3
            }}
            transition={{
              opacity: { duration: 2, repeat: isHovered ? Infinity : 0, repeatType: "loop" }
            }}
          />

          <motion.div
            animate={{
              scale: isHovered ? [1, 1.1, 1] : 1,
            }}
            transition={{
              scale: { duration: 1.5, repeat: isHovered ? Infinity : 0, repeatType: "loop" }
            }}
          >
            {icon}
          </motion.div>
        </motion.div>

        <div>
          <motion.p
            className="text-sm font-medium text-gray-400 stat-label flex items-center"
            initial={{ opacity: 0, x: -20 }}
            animate={{ opacity: 1, x: 0 }}
            transition={{ duration: 0.5, delay: delay + 0.2 }}
          >
            <motion.span
              className={`inline-block w-1.5 h-1.5 rounded-full bg-gradient-to-r ${themeStyles.text.replace('text-', 'from-').replace('400', '500')} to-transparent mr-1.5`}
              animate={{
                scale: [1, 1.5, 1],
                opacity: [0.7, 1, 0.7]
              }}
              transition={{
                duration: 2,
                repeat: Infinity,
                repeatType: "loop"
              }}
            />
            {title}
          </motion.p>

          <div className="flex items-baseline">
            <motion.p
              className={`text-2xl font-semibold ${themeStyles.heading} stat-value`}
              initial={{ opacity: 0, scale: 0.5 }}
              animate={{
                opacity: 1,
                scale: 1,
                textShadow: isHovered ? `0 0 8px ${glowColor}` : "none"
              }}
              transition={{
                opacity: { duration: 0.5, delay: delay + 0.3 },
                scale: { duration: 0.5, delay: delay + 0.3 },
                textShadow: { duration: 0.3 }
              }}
            >
              {value}
            </motion.p>

            {change && (
              <motion.div
                className={`ml-2 text-sm ${isPositive ? 'text-green-500' : 'text-red-500'} flex items-center`}
                initial={{ opacity: 0, scale: 0 }}
                animate={{ opacity: 1, scale: 1 }}
                transition={{ duration: 0.5, delay: delay + 0.4 }}
              >
                <motion.svg
                  xmlns="http://www.w3.org/2000/svg"
                  className="h-3 w-3 mr-0.5"
                  viewBox="0 0 20 20"
                  fill="currentColor"
                  animate={{
                    y: isPositive ? [0, -2, 0] : [0, 2, 0],
                  }}
                  transition={{
                    duration: 1.5,
                    repeat: Infinity,
                    repeatType: "loop",
                    repeatDelay: 1
                  }}
                >
                  {isPositive ? (
                    <path fillRule="evenodd" d="M14.707 12.707a1 1 0 01-1.414 0L10 9.414l-3.293 3.293a1 1 0 01-1.414-1.414l4-4a1 1 0 011.414 0l4 4a1 1 0 010 1.414z" clipRule="evenodd" />
                  ) : (
                    <path fillRule="evenodd" d="M5.293 7.293a1 1 0 011.414 0L10 10.586l3.293-3.293a1 1 0 111.414 1.414l-4 4a1 1 0 01-1.414 0l-4-4a1 1 0 010-1.414z" clipRule="evenodd" />
                  )}
                </motion.svg>
                {change}
              </motion.div>
            )}
          </div>

          {subtitle && (
            <motion.p
              className="text-xs text-gray-500 mt-1"
              initial={{ opacity: 0 }}
              animate={{ opacity: 0.8 }}
              transition={{ delay: delay + 0.5 }}
            >
              {subtitle}
            </motion.p>
          )}
        </div>
      </div>
    </motion.div>
  );
};

export default StatCard;
