// Path: oratorpath/src/lib/models/practiceSession.model.js
import mongoose from 'mongoose';

const practiceSessionSchema = new mongoose.Schema(
  {
    // Store the Clerk ID to link to the User model/collection
    clerkId: {
      type: String,
      required: true,
      index: true, // Add an index for faster queries by clerkId
    },
    // Session details
    sessionDate: {
      type: Date,
      default: Date.now,
    },
    duration: {
      type: Number, // Duration in minutes
      required: true,
    },
    score: {
      type: Number, // Overall score for the session
      required: true,
    },
    // Metrics for the session
    metrics: {
      clarity: {
        type: Number,
        min: 0,
        max: 100,
      },
      pace: {
        type: Number,
        min: 0,
        max: 100,
      },
      confidence: {
        type: Number,
        min: 0,
        max: 100,
      },
      vocabulary: {
        type: Number,
        min: 0,
        max: 100,
      },
      engagement: {
        type: Number,
        min: 0,
        max: 100,
      },
      structure: {
        type: Number,
        min: 0,
        max: 100,
      },
    },
    // Topics covered in the session
    topicsCovered: {
      type: Number,
      default: 0,
    },
    // New words used in the session
    newWords: {
      type: Number,
      default: 0,
    },
    // Session type (e.g., 'practice', 'assessment', 'coaching')
    sessionType: {
      type: String,
      enum: ['practice', 'assessment', 'coaching'],
      default: 'practice',
    },
    // Notes or feedback for the session
    notes: {
      type: String,
    },
  },
  { timestamps: true } // Adds createdAt and updatedAt timestamps automatically
);

// Add an index on clerkId and sessionDate for efficient querying of user's history
practiceSessionSchema.index({ clerkId: 1, sessionDate: -1 });

const PracticeSession =
  mongoose.models.PracticeSession || mongoose.model('PracticeSession', practiceSessionSchema);

export default PracticeSession;
